// math.js
export const multiply = (a, b) => a * b;

// math.test.js
import { multiply } from './math';

test('multiplies positive numbers', () => {
  // Arrange
  const num1 = 5;
  const num2 = 10;

  // Act
  const result = multiply(num1, num2);

  // Assert
  expect(result).toBe(50);
});
